  "rewrite_sql": "-- Set timeouts to fail fast rather than queue behind other queries
SET lock_timeout = '2s';
SET statement_timeout = '5min';

-- Backfill orders.status = 'pending' where NULL in batches
DO $$
DECLARE
    batch_size INTEGER := 5000;
    rows_updated INTEGER;
BEGIN
    LOOP
        UPDATE orders
        SET status = 'pending'
        WHERE id IN (
            SELECT id
            FROM orders
            WHERE status IS NULL
            LIMIT batch_size
        );

        GET DIAGNOSTICS rows_updated = ROW_COUNT;
        EXIT WHEN rows_updated = 0;

        -- Brief pause between batches to release locks
        PERFORM pg_sleep(0.05);
    END LOOP;
END $$;

-- Backfill order_items.quantity = 1 in batches
-- Only update rows that aren't already 1 to minimize work
DO $$
DECLARE
    batch_size INTEGER := 5000;
    rows_updated INTEGER;
BEGIN
    LOOP
        UPDATE order_items
        SET quantity = 1
        WHERE id IN (
            SELECT id
            FROM order_items
            WHERE quantity != 1
            LIMIT batch_size
        );

        GET DIAGNOSTICS rows_updated = ROW_COUNT;
        EXIT WHEN rows_updated = 0;

        -- Brief pause between batches to release locks
        PERFORM pg_sleep(0.05);
    END LOOP;
END $$;",
  "notes": "Added lock_timeout (2s) and statement_timeout (5min) to fail fast instead of queueing indefinitely. Batched both UPDATEs into 5000-row chunks with 50ms pauses between batches to avoid holding ROW EXCLUSIVE locks for extended periods. Added WHERE quantity != 1 filter to the order_items UPDATE to only modify rows that actually need changing (the original had no WHERE clause and would have updated all 20k+ rows unconditionally). This allows concurrent transactions to proceed between batches and prevents table-level lock contention.",
